  "functions": [
    {
      "args": "",
      "name": "is_admin",
      "schema": "private",
      "definition": "CREATE OR REPLACE FUNCTION private.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())); $function$\n"
    },
    {
      "args": "",
      "name": "handle_new_user",
      "schema": "public",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  insert into public.profiles (id, name, email, avatar_url)\n  values (\n    new.id,\n    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'),\n    new.email,\n    new.raw_user_meta_data->>'avatar_url'\n  )\n  on conflict (id) do update set\n    email = excluded.email,\n    name = coalesce(public.profiles.name, excluded.name),\n    avatar_url = coalesce(public.profiles.avatar_url, excluded.avatar_url),\n    updated_at = now();\n  return new;\nend;\n$function$\n"
    },
    {
      "args": "",
      "name": "set_updated_at",
      "schema": "public",
      "definition": "CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$function$\n"
    },
    {
      "args": "",
      "name": "validate_registration_workshop",
      "schema": "public",
      "definition": "CREATE OR REPLACE FUNCTION public.validate_registration_workshop()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nbegin\n  if exists (\n    select 1 from public.workshops\n    where id = new.workshop_id\n      and status = 'cancelled'\n  ) then\n    raise exception 'Cannot register for a cancelled workshop';\n  end if;\n  return new;\nend;\n$function$\n"
    }
  ],
