-- SOURCE: backend/supabase/migrations/20261020123021_archive_linkedin_workshop.sql
-- Add one durable publication state. Stage 08 will extend this same contract.
-- Existing open/coming_soon/cancelled rows remain compatible.
alter table public.workshops drop constraint workshops_status_check;
alter table public.workshops add constraint workshops_status_check
  check (status in ('open', 'coming_soon', 'cancelled', 'archived'));

-- Verified against project epgsgvwdlwarktbjrdfn on 20 October 2026.
-- Never archive records based only on a title/slug match. On another database
-- where this exact record is absent, leave its data alone; do not create a row.
do $$
declare target public.workshops%rowtype;
begin
  select * into target from public.workshops
    where id = 'be33c1fc-e4c4-4def-b33e-078fdf662400' for update;
  if not found then
    raise notice 'Verified LinkedIn workshop ID is absent; no workshop archived.';
    return;
  end if;
  if target.slug is distinct from 'linkedin-workshop'
     or target.title is distinct from 'LinkedIn Workshop'
     or target.host_name is distinct from 'F1 Forge'
     or target.starts_at is distinct from timestamptz '2026-10-02 14:00:00+00'
     or target.ends_at is distinct from timestamptz '2026-10-02 15:00:00+00' then
    raise exception 'LinkedIn workshop identity mismatch; review metadata before archiving.';
  end if;
  update public.workshops set status = 'archived' where id = target.id;
end;
$$;

-- Restrictive policies add only an archival veto alongside existing ownership
-- and admin policies. They grant no new access and preserve all historical rows.
create policy "Archived workshops reject new registrations"
  on public.registrations as restrictive for insert to authenticated
  with check (exists (
    select 1 from public.workshops w
    where w.id = registrations.workshop_id and w.status <> 'archived'
  ));

create policy "Archived workshops hide meeting links"
  on public.workshop_links as restrictive for select to authenticated
  using (exists (
    select 1 from public.workshops w
    where w.id = workshop_links.workshop_id and w.status <> 'archived'
  ));

-- SOURCE: backend/supabase/migrations/20261021181340_workshop_lifecycle_contract.sql
-- Prompt 08: compatible publication/schedule contract. No data is rewritten.
-- Apply only after drift review and the existing public/archival migrations.
-- Registration/link authorization policies belong to prompts 09 and 10.

alter table public.workshops add constraint workshops_lifecycle_schedule_check
check (
  status in ('cancelled', 'archived')
  or (status = 'coming_soon' and starts_at is null and ends_at is null)
  or (starts_at is not null and ends_at is not null
      and isfinite(starts_at) and isfinite(ends_at) and ends_at > starts_at)
) not valid;

-- NOT VALID preserves legacy rows, while checking new rows and later updates.
-- Validate separately after existing inconsistencies have been reviewed.
-- Pure, invoker-rights predicates for the next two services; no public RPC,
-- data reads, grants, policies, security-definer code or caller-supplied clock
-- is installed as an authorization path here.
create schema if not exists workify_private;

create function workify_private.workshop_schedule_valid(start_time timestamptz, end_time timestamptz)
returns boolean language sql immutable security invoker set search_path = '' as $$
  select coalesce(start_time is not null and end_time is not null
    and isfinite(start_time) and isfinite(end_time) and end_time > start_time, false);
$$;

create function workify_private.workshop_lifecycle_state(publication text, start_time timestamptz, end_time timestamptz, at_time timestamptz)
returns text language sql immutable security invoker set search_path = '' as $$
  select case
    when publication in ('archived', 'cancelled') then publication
    when publication is null or publication not in ('open', 'coming_soon')
      or at_time is null or not isfinite(at_time) then 'unavailable'
    when publication = 'coming_soon' and start_time is null and end_time is null then 'unscheduled'
    when not workify_private.workshop_schedule_valid(start_time, end_time) then 'unavailable'
    when at_time >= end_time then 'completed'
    when publication = 'coming_soon' then 'coming-soon'
    when at_time >= start_time then 'ongoing'
    else 'scheduled'
  end;
$$;

create function workify_private.workshop_registration_eligible(publication text, start_time timestamptz, end_time timestamptz, at_time timestamptz)
returns boolean language sql immutable security invoker set search_path = '' as $$
  select workify_private.workshop_lifecycle_state(publication, start_time, end_time, at_time) = 'scheduled';
$$;

create function workify_private.workshop_join_eligible(publication text, start_time timestamptz, end_time timestamptz, at_time timestamptz)
returns boolean language sql immutable security invoker set search_path = '' as $$
  select coalesce(publication = 'open' and workify_private.workshop_schedule_valid(start_time, end_time)
    and at_time is not null and isfinite(at_time)
    and at_time >= start_time - interval '15 minutes' and at_time < end_time, false);
$$;

revoke all on function workify_private.workshop_schedule_valid(timestamptz,timestamptz) from public, anon, authenticated;
revoke all on function workify_private.workshop_lifecycle_state(text,timestamptz,timestamptz,timestamptz) from public, anon, authenticated;
revoke all on function workify_private.workshop_registration_eligible(text,timestamptz,timestamptz,timestamptz) from public, anon, authenticated;
revoke all on function workify_private.workshop_join_eligible(text,timestamptz,timestamptz,timestamptz) from public, anon, authenticated;

-- SOURCE: backend/supabase/migrations/20261022170525_registration_service.sql
-- Prompt 09. Source only: review schema/policy drift before applying.
-- Requires the archival and lifecycle migrations. No history is rewritten.
-- Retain the existing unique(user_id, workshop_id) constraint and read policies.
alter table public.registrations enable row level security;

-- Restrictive ownership checks remain effective even if a permissive policy is
-- later added. Admin read access is unchanged; admin is not an attendee bypass.
create policy "Registration inserts require current owner"
  on public.registrations as restrictive for insert to authenticated
  with check ((select auth.uid()) is not null and (select auth.uid()) = user_id);
create policy "Registration deletes require current owner"
  on public.registrations as restrictive for delete to authenticated
  using ((select auth.uid()) is not null and (select auth.uid()) = user_id);
create policy "Registration identity and history are immutable"
  on public.registrations as restrictive for update to authenticated
  using (false) with check (false);
revoke insert, update, delete, truncate, references, trigger on public.registrations from public;
revoke insert, update, delete, truncate, references, trigger on public.registrations from anon;
revoke update, truncate, references, trigger on public.registrations from authenticated;
grant select, insert, delete on public.registrations to authenticated;

-- This private trigger needs definer rights solely to lock a workshop row:
-- attendees cannot UPDATE workshops or take row locks under its admin RLS.
-- It returns no workshop data, is not an RPC, and validates auth.uid itself.
create function workify_private.guard_registration_mutation()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  attendee uuid := auth.uid();
  target public.workshops%rowtype;
  owner_id uuid;
  workshop_id uuid;
  checked_at timestamptz;
begin
  if tg_op = 'DELETE' then
    owner_id := old.user_id;
    workshop_id := old.workshop_id;
  else
    owner_id := new.user_id;
    workshop_id := new.workshop_id;
  end if;
  if attendee is null or attendee is distinct from owner_id then
    raise exception using errcode = '42501', message = 'Sign in to manage your own registration.';
  end if;

  -- SHARE conflicts with schedule/status UPDATEs, while allowing parallel
  -- registrations. Recheck with the server clock AFTER any row-lock wait.
  select w.* into target from public.workshops w where w.id = workshop_id for share;
  checked_at := clock_timestamp();
  if not found or not workify_private.workshop_registration_eligible(
      target.status, target.starts_at, target.ends_at, checked_at) then
    raise exception using errcode = 'P0001',
      message = 'Registration and cancellation are available only for open workshops before they start.';
  end if;
  if tg_op = 'INSERT' then
    new.created_at := checked_at;
    return new;
  end if;
  return old;
end;
$$;
revoke all on function workify_private.guard_registration_mutation() from public, anon, authenticated;
create trigger registrations_lifecycle_guard
  before insert or delete on public.registrations
  for each row execute function workify_private.guard_registration_mutation();

-- No UPDATE policy is installed. Cancellation removes only an eligible future
-- reservation. Ongoing/completed/cancelled/archived records cannot be deleted
-- by this path. Attendance/reviews are separate facts and are never mutated.

-- SOURCE: backend/supabase/migrations/20261022172429_meeting_link_access.sql
-- Prompt 10 source only. Review drift and apply 03/08/09 first.
create function workify_private.meeting_access_now()
returns timestamptz language sql volatile security invoker set search_path = '' as $$
  select clock_timestamp();
$$;
revoke all on function workify_private.meeting_access_now() from public, anon, authenticated;
grant usage on schema workify_private to anon, authenticated;
grant execute on function workify_private.meeting_access_now() to anon, authenticated;
alter table public.workshop_links enable row level security;
alter table public.workshop_links add constraint workshop_links_google_meet_url_check
  check (meet_url = '' or meet_url ~ '^https://meet[.]google[.]com/[a-z]{3}-[a-z]{4}-[a-z]{3}$') not valid;
-- Legacy rows stay intact; unsafe descriptions are hidden until corrected.
alter table public.workshops add constraint workshops_public_descriptions_check
  check (concat_ws(' ',slug,title,host_name,mode,timezone,short_description,full_description,array_to_string(tags,' '))
    !~* 'meet[.]google[.]com') not valid;
create policy "Public descriptions exclude meeting addresses"
  on public.workshops as restrictive for select to anon, authenticated
  using (concat_ws(' ',slug,title,host_name,mode,timezone,short_description,full_description,array_to_string(tags,' '))
    !~* 'meet[.]google[.]com');

-- Restrictive veto alongside existing owner/admin policies. Admin management
-- may read active publications outside the join window; cancelled/archived
-- publications veto every client read, including admins.
create policy "Meeting reads require eligible attendee or active admin management"
  on public.workshop_links as restrictive for select to anon, authenticated
  using (
    (select auth.uid()) is not null
    and (meet_url = '' or meet_url ~ '^https://meet[.]google[.]com/[a-z]{3}-[a-z]{4}-[a-z]{3}$')
    and exists (select 1 from public.workshops w where w.id = workshop_links.workshop_id
      and w.status in ('open','coming_soon')
      and ((select private.is_admin()) or (
        w.status = 'open' and w.starts_at is not null and w.ends_at is not null
        and isfinite(w.starts_at) and isfinite(w.ends_at) and w.ends_at > w.starts_at
        and workify_private.meeting_access_now() >= w.starts_at - interval '15 minutes'
        and workify_private.meeting_access_now() < w.ends_at
        and exists (select 1 from public.registrations r
          where r.workshop_id = w.id and r.user_id = (select auth.uid()))
      ))
    )
  );
create policy "Meeting inserts require active publication"
  on public.workshop_links as restrictive for insert to authenticated
  with check (exists (select 1 from public.workshops w where w.id = workshop_links.workshop_id
    and w.status in ('open','coming_soon')));
create policy "Meeting updates require active publication"
  on public.workshop_links as restrictive for update to authenticated
  using (exists (select 1 from public.workshops w where w.id = workshop_links.workshop_id
    and w.status in ('open','coming_soon')))
  with check (exists (select 1 from public.workshops w where w.id = workshop_links.workshop_id
    and w.status in ('open','coming_soon')));

-- Pure predicates read no data. Their supplied test clock is never authority
-- for a public endpoint. The trigger and other private functions stay revoked.
grant usage on schema workify_private to authenticated;
grant execute on function workify_private.workshop_schedule_valid(timestamptz,timestamptz) to authenticated;
grant execute on function workify_private.workshop_join_eligible(text,timestamptz,timestamptz,timestamptz) to authenticated;

create function public.get_workshop_join_state(p_workshop_id uuid)
returns jsonb language plpgsql volatile security invoker set search_path = '' as $$
declare
  attendee uuid := auth.uid();
  target public.workshops%rowtype;
  checked_at timestamptz;
  link text;
  refresh_ms integer;
begin
  if attendee is null then return jsonb_build_object('status','unauthorized'); end if;
  if not exists (select 1 from public.registrations r
    where r.workshop_id = p_workshop_id and r.user_id = attendee) then
    return jsonb_build_object('status','unauthorized');
  end if;
  select w.* into target from public.workshops w where w.id = p_workshop_id;
  if not found then return jsonb_build_object('status','unavailable'); end if;
  checked_at := workify_private.meeting_access_now();
  if target.status not in ('open','coming_soon') or not workify_private.workshop_schedule_valid(target.starts_at,target.ends_at) then
    return jsonb_build_object('status','unavailable');
  end if;
  if checked_at >= target.ends_at then return jsonb_build_object('status','ended'); end if;
  if target.status <> 'open' then return jsonb_build_object('status','unavailable'); end if;
  if checked_at < target.starts_at - interval '15 minutes' then
    refresh_ms := greatest(1,least(30000,floor(extract(epoch from (target.starts_at - interval '15 minutes' - checked_at))*1000)))::integer;
    return jsonb_build_object('status','upcoming','refresh_after_ms',refresh_ms);
  end if;
  select l.meet_url into link from public.workshop_links l where l.workshop_id = p_workshop_id;
  -- RLS may deny a changed schedule/status. Recheck end after the read, too.
  checked_at := workify_private.meeting_access_now();
  if checked_at >= target.ends_at then return jsonb_build_object('status','ended'); end if;
  refresh_ms := greatest(1,least(30000,floor(extract(epoch from (target.ends_at-checked_at))*1000)))::integer;
  if not workify_private.workshop_join_eligible(target.status,target.starts_at,target.ends_at,checked_at)
    or link is null or link !~ '^https://meet[.]google[.]com/[a-z]{3}-[a-z]{4}-[a-z]{3}$' then
    return jsonb_build_object('status','unavailable','refresh_after_ms',refresh_ms);
  end if;
  return jsonb_build_object('status','joinable','meet_url',link,'refresh_after_ms',refresh_ms);
end;
$$;
revoke all on function public.get_workshop_join_state(uuid) from public, anon, authenticated;
grant execute on function public.get_workshop_join_state(uuid) to authenticated;

-- SOURCE: backend/supabase/migrations/20261023070718_profile_editor_contract.sql
-- Prompt 12: source only. Inspect deployed schema/policy drift before applying.
-- Requires existing profiles, avatars bucket/storage policies and workify_private.
-- No profile, auth or object data is rewritten or deleted.
alter table public.profiles enable row level security;
revoke insert, update, delete, truncate, references, trigger on public.profiles from public, anon, authenticated;
revoke update(id,email,created_at,updated_at) on public.profiles from public, anon, authenticated;
revoke select on public.profiles from public, anon;
grant select on public.profiles to authenticated;
grant update(name,handle,bio,college,location,skills,linkedin_url,x_url,website_url,avatar_url)
  on public.profiles to authenticated;
create policy "Profile updates require current owner" on public.profiles
  as restrictive for update to authenticated
  using ((select auth.uid()) is not null and (select auth.uid()) = id)
  with check ((select auth.uid()) is not null and (select auth.uid()) = id);

-- Invoker trigger; no table reads, secrets or new RPC. Existing auth bootstrap
-- may insert an empty name; valid names are required when the user edits it.
create function workify_private.validate_profile_edit()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare
  link text;
  skill text;
begin
  new.name := btrim(new.name);
  new.handle := nullif(lower(regexp_replace(btrim(new.handle), '^@', '')), '');
  if new.name is null or length(new.name) not between 1 and 50 then
    raise exception using errcode='23514', message='Name must contain 1 to 50 characters.';
  end if;
  if length(coalesce(new.bio,'')) > 500 or length(coalesce(new.college,'')) > 100
      or length(coalesce(new.location,'')) > 100 then
    raise exception using errcode='23514', message='Profile text exceeds its length limit.';
  end if;
  if cardinality(coalesce(new.skills,'{}')) > 10 or coalesce(array_ndims(new.skills),1) > 1 then
    raise exception using errcode='23514', message='Use up to 10 skills.';
  end if;
  foreach skill in array coalesce(new.skills,'{}') loop
    if skill is null or length(btrim(skill)) not between 1 and 30 then
      raise exception using errcode='23514', message='Skills must contain 1 to 30 characters.';
    end if;
  end loop;
  foreach link in array array[new.linkedin_url,new.x_url,new.website_url] loop
    if coalesce(link,'') <> '' and (
      length(link) > 2048 or link ~ '[[:space:]\\]' or link ~ '[[:cntrl:]]'
      or link !~ '^https://([A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?|\[[0-9A-Fa-f:]+\])(:[0-9]{1,5})?([/?#].*)?$'
    ) then
      raise exception using errcode='23514', message='Contact links must be valid HTTPS URLs without credentials.';
    end if;
  end loop;
  return new;
end;
$$;
revoke all on function workify_private.validate_profile_edit() from public, anon, authenticated;
create trigger profiles_validate_edit before update on public.profiles
  for each row execute function workify_private.validate_profile_edit();

-- Keep intentionally public avatars public. Fail closed on unexpected setup
-- rather than silently change a private bucket's visibility or create a bucket.
do $$ begin
  if not exists(select 1 from storage.buckets where id='avatars' and public) then
    raise exception 'Expected the existing public avatars bucket; review storage configuration.';
  end if;
end $$;
update storage.buckets set file_size_limit=2097152,
  allowed_mime_types=array['image/jpeg','image/png','image/webp','image/gif'] where id='avatars';

-- Restrictive checks also protect against additional permissive storage policies.
-- Other buckets retain their existing access model. Public SELECT is unchanged.
create policy "Avatar insert owner boundary" on storage.objects as restrictive for insert to authenticated
  with check (bucket_id <> 'avatars' or (
    (select auth.uid()) is not null and split_part(name,'/',1)=(select auth.uid())::text
    and name ~ '^[^/]+/[A-Za-z0-9][A-Za-z0-9._-]*[.](jpg|jpeg|png|webp|gif)$'
  ));
create policy "Avatar update owner boundary" on storage.objects as restrictive for update to authenticated
  using (bucket_id <> 'avatars' or ((select auth.uid()) is not null and split_part(name,'/',1)=(select auth.uid())::text))
  with check (bucket_id <> 'avatars' or (
    (select auth.uid()) is not null and split_part(name,'/',1)=(select auth.uid())::text
    and name ~ '^[^/]+/[A-Za-z0-9][A-Za-z0-9._-]*[.](jpg|jpeg|png|webp|gif)$'
  ));
create policy "Avatar delete owner boundary" on storage.objects as restrictive for delete to authenticated
  using (bucket_id <> 'avatars' or ((select auth.uid()) is not null and split_part(name,'/',1)=(select auth.uid())::text));

-- SOURCE: backend/supabase/migrations/20261023081331_admin_workshop_contract.sql
-- Prompt 13: unapplied source. Review live schema/history/column grants first.
-- Requires prior lifecycle, registration and meeting access contracts.
alter table public.workshops enable row level security;
alter table public.workshop_links enable row level security;
revoke insert, update, delete, truncate, references, trigger on public.workshops from public, anon, authenticated;
revoke update(id,created_at,updated_at) on public.workshops from public, anon, authenticated;
grant insert(slug,title,host_name,mode,status,short_description,full_description,tags,starts_at,ends_at,timezone),
  update(slug,title,host_name,mode,status,short_description,full_description,tags,starts_at,ends_at,timezone)
  on public.workshops to authenticated;
create policy "Workshop inserts require authoritative admin" on public.workshops as restrictive
  for insert to authenticated with check ((select auth.uid()) is not null and (select private.is_admin()));
create policy "Workshop updates require authoritative admin" on public.workshops as restrictive
  for update to authenticated using ((select auth.uid()) is not null and (select private.is_admin()))
  with check ((select auth.uid()) is not null and (select private.is_admin()));

revoke insert, update, delete, truncate, references, trigger on public.workshop_links from public, anon, authenticated;
-- PostgREST upsert includes its conflict key in the UPDATE projection, so grant
-- that column while the trigger below forbids actually changing its identity.
grant insert(workshop_id,meet_url), update(workshop_id,meet_url) on public.workshop_links to authenticated;
create policy "Meeting inserts require authoritative admin" on public.workshop_links as restrictive
  for insert to authenticated with check ((select auth.uid()) is not null and (select private.is_admin()));
create policy "Meeting updates require authoritative admin" on public.workshop_links as restrictive
  for update to authenticated using ((select auth.uid()) is not null and (select private.is_admin()))
  with check ((select auth.uid()) is not null and (select private.is_admin()));

-- Clients cannot edit membership or hard-delete a workshop/history chain.
revoke insert, update, delete, truncate, references, trigger on public.admin_users from public, anon, authenticated;

-- Invoker trigger: validation only, never an authorization RPC or definer bypass.
create function workify_private.validate_admin_workshop()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare tag text;
begin
  if new.id='be33c1fc-e4c4-4def-b33e-078fdf662400'::uuid and new.status <> 'archived' then
    raise exception using errcode='23514',message='The retired workshop must remain archived.';
  end if;
  -- Status-only closure preserves legacy metadata and registration history.
  -- Existing schedule/description constraints still independently apply.
  if tg_op='UPDATE' and new.status in ('cancelled','archived')
     and (to_jsonb(new)-'status'-'updated_at') = (to_jsonb(old)-'status'-'updated_at') then
    return new;
  end if;
  new.slug := lower(btrim(new.slug)); new.title := btrim(new.title); new.host_name := btrim(new.host_name);
  new.timezone := btrim(new.timezone);
  if new.slug is null or length(new.slug) not between 3 and 80 or new.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then
    raise exception using errcode='23514',message='Use a 3 to 80 character lowercase slug with single hyphens.';
  end if;
  if new.title is null or length(new.title) not between 1 and 160 or new.host_name is null or length(new.host_name) not between 1 and 100 then
    raise exception using errcode='23514',message='Title and host are required within their length limits.';
  end if;
  if length(coalesce(new.short_description,'')) > 500 or length(coalesce(new.full_description,'')) > 12000 then
    raise exception using errcode='23514',message='Description length exceeds the limit.';
  end if;
  if cardinality(coalesce(new.tags,'{}')) > 10 or coalesce(array_ndims(new.tags),1) > 1 then
    raise exception using errcode='23514',message='Use up to 10 tags.';
  end if;
  foreach tag in array coalesce(new.tags,'{}') loop
    if tag is null or length(btrim(tag)) not between 1 and 40 then
      raise exception using errcode='23514',message='Tags must contain 1 to 40 characters.';
    end if;
  end loop;
  if new.timezone is null or length(new.timezone) > 100 or not exists (
    select 1 from pg_catalog.pg_timezone_names where lower(name)=lower(new.timezone)
  ) then
    raise exception using errcode='23514',message='Provide a valid display timezone.';
  end if;
  if new.mode is distinct from 'Online — Google Meet' then
    raise exception using errcode='23514',message='Unsupported workshop mode.';
  end if;
  return new;
end;
$$;
revoke all on function workify_private.validate_admin_workshop() from public, anon, authenticated;
create trigger workshops_validate_admin before insert or update on public.workshops
  for each row execute function workify_private.validate_admin_workshop();

create function workify_private.keep_meeting_identity()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  if new.workshop_id is distinct from old.workshop_id then
    raise exception using errcode='23514',message='Meeting workshop identity cannot be changed.';
  end if;
  return new;
end;
$$;
revoke all on function workify_private.keep_meeting_identity() from public, anon, authenticated;
create trigger workshop_links_keep_identity before update on public.workshop_links
  for each row execute function workify_private.keep_meeting_identity();

